import { cn } from "@/lib/utils"

/**
 * Webfluence circular badge logo, recreated as vector: a thin ring, the
 * handwritten "WF." monogram (Caveat), and the curved "WEBFLUENCE PVT LTD"
 * legend. Uses currentColor so it inherits light/dark text color.
 *
 * To use the exact artwork instead, drop the file at /public/webfluence-logo.svg
 * (or .png) and replace the <svg> below with <img src="/webfluence-logo.svg" />.
 */
export function Logo({
  className,
  showWordmark = true,
  invert = false,
}: {
  className?: string
  showWordmark?: boolean
  invert?: boolean
}) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", className)}>
      <span className={cn("relative inline-block h-10 w-10", invert ? "text-white" : "text-foreground")}>
        <svg viewBox="0 0 100 100" className="h-full w-full" fill="none" aria-label="Webfluence">
          <circle cx="50" cy="49" r="45" stroke="currentColor" strokeWidth="1.4" />
          <text
            x="50"
            y="52"
            textAnchor="middle"
            dominantBaseline="middle"
            fill="currentColor"
            style={{ fontFamily: "var(--font-hand), cursive", fontSize: "42px", fontWeight: 700 }}
          >
            WF.
          </text>
          <defs>
            <path id="wf-legend" d="M 15 58 A 38 38 0 0 1 85 58" fill="none" />
          </defs>
          <text
            fill="currentColor"
            style={{ fontFamily: "var(--font-sans), sans-serif", fontSize: "6px", fontWeight: 600, letterSpacing: "1.4px" }}
          >
            <textPath href="#wf-legend" startOffset="50%" textAnchor="middle">
              WEBFLUENCE PVT LTD
            </textPath>
          </text>
        </svg>
      </span>
      {showWordmark && (
        <span className={cn("text-xl font-bold tracking-tight", invert ? "text-white" : "text-foreground")}>
          Webfluence<span className="text-brand-cyan">.</span>
        </span>
      )}
    </span>
  )
}
